int convert_path_component(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int ret = 0;
    unsigned char *src = from;
    unsigned char *dst = to;
    int remaining = tolen;

    while (fromlen > 0) {
        int component_len = *src++;

        if (component_len == 0) {
            continue;  // Skip empty components
        }

        if (component_len > fromlen - 1) {
            return -ENAMETOOLONG;
        }

        if (component_len > remaining) {
            return -ENAMETOOLONG;
        }

        memcpy(dst, src, component_len);
        dst += component_len;
        remaining -= component_len;

        *dst = '\0';
        remaining -= 1;

        src += component_len;
        fromlen -= (component_len + 1);
    }

    return ret;
}

int path_to_user(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0, j = 0;

    while (i < fromlen) {
        int namelen = from[i];

        if (namelen == 0)
            namelen = fromlen - i - 1;

        if (j + namelen + 1 > tolen)
            return -ENAMETOOLONG;

        if (namelen) {
            memcpy(to + j, from + i + 1, namelen);
            j += namelen;
        }

        if (i + namelen + 1 >= fromlen)
            break;

        i += namelen + 1;

        if (j < tolen) {
            to[j++] = '/';
        }
    }

    if (j < tolen)
        to[j] = '\0';
    else {
        return -ENAMETOOLONG;
    }

    return 0;
}

int convert_path_component(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int pos = 0;
    int i = 0;

    while (i < fromlen) {
        if (pos >= tolen - 1) {
            return -ENAMETOOLONG;
        }

        if (from[i] == 0) {
            to[pos++] = '.';
            i++;
        } else if (from[i] == 1) {
            to[pos++] = '.';
            if (pos >= tolen - 1) {
                return -ENAMETOOLONG;
            }
            to[pos++] = '.';
            i++;
        } else {
            int len = from[i];
            i++;
            if (i + len > fromlen) {
                return -EIO;
            }
            while (len--) {
                if (pos >= tolen - 1) {
                    return -ENAMETOOLONG;
                }
                to[pos++] = from[i];
                i++;
            }
        }
    }

    if (pos >= tolen) {
        return -ENAMETOOLONG;
    }
    to[pos] = '\0';
    return 0;
}

int from_path(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int res = 0;
    int i;
    int j;
    int name_len;
    int pos = 0;

    for (i = 0; i < fromlen; i += name_len + 1) {
        name_len = from[i];

        if (name_len == 0) {
            continue;
        }

        if (name_len > tolen) {
            return -ENAMETOOLONG;
        }

        if (pos + name_len > tolen) {
            return -ENAMETOOLONG;
        }

        for (j = 0; j < name_len; j++) {
            to[pos++] = from[i + 1 + j];
        }

        to[pos++] = '/';
    }

    if (pos > 0 && pos <= tolen) {
        to[pos - 1] = '\0';
    } else {
        return -EIO;
    }

    return 0;
}

int nameidata_to_path(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int ret = 0;
    int pos = 0;
    int i = 0;

    while (i < fromlen && pos < tolen - 1) {
        unsigned char type = from[i++];
        int namelen = from[i++];

        if (i + namelen > fromlen) {
            return -EIO;
        }

        if (pos > 0 && to[pos - 1] != '/') {
            if (pos >= tolen - 1) {
                return -ENAMETOOLONG;
            }
            to[pos++] = '/';
        }

        for (int j = 0; j < namelen && pos < tolen - 1; j++) {
            to[pos++] = from[i++];
        }

        if (type == DT_WHT && pos < tolen - 1) {
            to[pos++] = '@';
        }
    }

    if (pos >= tolen) {
        return -ENAMETOOLONG;
    }

    to[pos] = '\0';

    return ret;
}
